import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8IeflXD.js";var i=JSON.parse(`{"title":"Alternatives rejected","description":"","frontmatter":{},"headers":[],"relativePath":"why-alternatives.md","filePath":"pages/why-alternatives.md"}`),a={name:`why-alternatives.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="alternatives-rejected" tabindex="-1">Alternatives rejected <a class="header-anchor" href="#alternatives-rejected" aria-label="Permalink to “Alternatives rejected”">​</a></h1><p>Four shapes were considered and dropped. Each one is recorded with what was kept from it, which for three of them is nothing.</p><h2 id="a-row-pipeline-plus-a-flat-column-list" tabindex="-1">A row pipeline plus a flat column list <a class="header-anchor" href="#a-row-pipeline-plus-a-flat-column-list" aria-label="Permalink to “A row pipeline plus a flat column list”">​</a></h2><p>The shape both comparable libraries take. Rejected because the transpose becomes a second code path: every stage that reads a row would need a column twin, and the branch on orientation would appear once per stage instead of never.</p><p>The one-axis shape also forces header nesting into a separate pass, which is a dedicated builder in one library and a separate grouping model in the other. Here the column axis is already a forest, so nesting is <code>flattenAxis</code> in <code>src/1_axis.ts</code> called with a predicate that always answers open.</p><p>Kept from it: nothing. The bill is the cost table on <a href="/hafley-rxjs/signal-grid/why-forests">Two ordered forests</a>.</p><h2 id="a-pixel-width-solver-in-the-package" tabindex="-1">A pixel width solver in the package <a class="header-anchor" href="#a-pixel-width-solver-in-the-package" aria-label="Permalink to “A pixel width solver in the package”">​</a></h2><p>Rejected and deleted, with the measurement behind it and the consequence spelled out on <a href="/hafley-rxjs/signal-grid/why-no-solver">No layout algorithm</a>.</p><p>Kept from it: the declared width, minimum, maximum, and flex keys on <code>ColumnDef</code>, which are now constraints handed to the layout engine rather than inputs to arithmetic.</p><h2 id="filtering-inside-the-kernel" tabindex="-1">Filtering inside the kernel <a class="header-anchor" href="#filtering-inside-the-kernel" aria-label="Permalink to “Filtering inside the kernel”">​</a></h2><p><code>filterAxis</code> in <code>src/1_axis.ts</code> and <code>buildRowPredicate</code> in <code>src/2_operators.ts</code> are written, tested, and called by nothing. <code>GridState</code> carries no filter key, so a filter model would be state that no stage reads.</p><p>The reason is recorded inside the parity generator rather than in prose, so the matrix cannot disagree with it, and tagging the row filter feature as implemented fails the parity run.</p><p>Kept from it: both functions, and <code>FilterMode</code> in <code>src/0_types.ts</code>, which exists because a tree filter has three defensible answers: prune the tree, keep ancestors, or keep whole subtrees. Picking one of the three without a caller would have been the actual mistake.</p><h2 id="aggregation-column-typing-and-inline-editing" tabindex="-1">Aggregation, column typing, and inline editing <a class="header-anchor" href="#aggregation-column-typing-and-inline-editing" aria-label="Permalink to “Aggregation, column typing, and inline editing”">​</a></h2><table tabindex="0"><thead><tr><th>cut</th><th>why</th></tr></thead><tbody><tr><td>aggregation</td><td>arithmetic over a group rather than a relational operator; a group heading carries its key and its children and nothing else</td></tr><tr><td>column typing as a driver</td><td><code>ColumnType</code> reaches the comparator and the operator set and stops there</td></tr><tr><td>inline editing</td><td>the consumer owns the form lifecycle; <code>state.editing</code> is read by the renderer and written by no epic</td></tr></tbody></table><p>Each one carries its reason in the same generator, so the parity matrix and this page cannot drift apart.</p><h2 id="what-is-available-and-unused" tabindex="-1">What is available and unused <a class="header-anchor" href="#what-is-available-and-unused" aria-label="Permalink to “What is available and unused”">​</a></h2><table tabindex="0"><thead><tr><th>thing</th><th>state</th></tr></thead><tbody><tr><td><code>mapAxis</code> in <code>src/1_axis.ts</code></td><td>written, no caller; structure would be shared by reference</td></tr><tr><td><code>ancestorsOf</code> in <code>src/1_axis.ts</code></td><td>reached only through <code>filterAxis</code>, which has no caller</td></tr><tr><td><code>rowOrder</code></td><td>a state key with no reader</td></tr><tr><td><code>query.expand</code></td><td>hardcoded to nothing, so server tree loading has no kernel trigger</td></tr><tr><td>column virtualization</td><td>not attempted; it is the same window on the other axis</td></tr></tbody></table><h2 id="still-unwired-in-the-renderer" tabindex="-1">Still unwired in the renderer <a class="header-anchor" href="#still-unwired-in-the-renderer" aria-label="Permalink to “Still unwired in the renderer”">​</a></h2><table tabindex="0"><thead><tr><th>gap</th><th>where it stops</th></tr></thead><tbody><tr><td>the header group band</td><td><code>src/10_render.ts</code> drops group nodes before the header is built</td></tr><tr><td>eight declared slots</td><td><code>headerGroup</code>, <code>row</code>, <code>checkbox</code>, <code>resizeHandle</code>, <code>dragPreview</code>, <code>empty</code>, <code>loading</code>, <code>footer</code></td></tr><tr><td>a focus ring</td><td><code>state.focus</code> has no renderer</td></tr><tr><td>the transposed cell values</td><td>a cell reads from the row axis&#39;s map, covered on <a href="/hafley-rxjs/signal-grid/why-seats">The seat table</a></td></tr></tbody></table><p>The generated three-way matrix is on <a href="/hafley-rxjs/signal-grid/parity">Feature parity</a>, and it is rebuilt from the tags in <code>src/</code> rather than written by hand.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};